function drawWrappedText(ctx:CanvasRenderingContext2D,text:string,x:number,y:number,maxWidth:number,lineHeight:number,maxLines=3){const lines:string[]=[];let line='';for(const char of text){const next=line+char;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=char}else line=next}if(line)lines.push(line);lines.slice(0,maxLines).forEach((value,index)=>ctx.fillText(value,x,y+index*lineHeight));return Math.min(lines.length,maxLines)}
function renderCompletionCard(session:PracticeSession,mode:CompletionCardMode){return new Promise<Blob>((resolve,reject)=>{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');if(!ctx){reject(new Error('Canvas unavailable'));return}const w=canvas.width,h=canvas.height,stamp=session.completedAt??Date.now(),headline=mode==='recorded'?`记录了 ${formatCardElapsed(session.recordedSeconds??sessionElapsedSeconds(session))}`:`给自己留了 ${cardDuration(session)}`,label=mode==='recorded'?'PRACTICE RECORD / 01':'SESSION COMPLETE / 01',quote=mode==='recorded'?'今天先做到这里，也算给自己留出了空间。':'现在，回到你想继续的事。';ctx.fillStyle='#07100e';ctx.fillRect(0,0,w,h);const wash=ctx.createLinearGradient(0,0,w,h);wash.addColorStop(0,'rgba(220,244,229,.12)');wash.addColorStop(.48,'rgba(7,16,14,0)');wash.addColorStop(1,'rgba(133,186,153,.1)');ctx.fillStyle=wash;ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(225,245,232,.08)';ctx.lineWidth=1;for(let y=150;y<h-100;y+=42){ctx.beginPath();ctx.moveTo(70,y);ctx.lineTo(w-70,y);ctx.stroke()}ctx.strokeStyle='rgba(225,245,232,.35)';ctx.lineWidth=2;ctx.strokeRect(54,54,w-108,h-108);ctx.strokeStyle='rgba(225,245,232,.12)';ctx.lineWidth=1;ctx.strokeRect(72,72,w-144,h-144);ctx.fillStyle='rgba(232,248,237,.68)';ctx.font='500 22px monospace';ctx.fillText('H E R  M O T I O N',82,118);ctx.textAlign='right';ctx.fillStyle='rgba(232,248,237,.48)';ctx.font='18px monospace';ctx.fillText(formatCardDate(stamp),w-82,118);ctx.textAlign='left';ctx.strokeStyle='rgba(201,236,211,.32)';ctx.beginPath();ctx.moveTo(82,174);ctx.lineTo(308,174);ctx.stroke();ctx.fillStyle='rgba(232,248,237,.55)';ctx.font='18px monospace';ctx.fillText(label,82,214);ctx.fillStyle='#f2fbf4';ctx.font='500 62px "PingFang SC", "Microsoft YaHei", sans-serif';drawWrappedText(ctx,headline,82,350,870,78,2);ctx.fillStyle='rgba(232,248,237,.7)';ctx.font='28px "PingFang SC", "Microsoft YaHei", sans-serif';drawWrappedText(ctx,session.title,82,520,820,42,2);ctx.fillStyle='rgba(232,248,237,.46)';ctx.font='20px monospace';ctx.fillText(`${cardMode(session)}  ·  ${session.exerciseIds.length} 个动作`,82,620);ctx.strokeStyle='rgba(225,245,232,.16)';ctx.beginPath();ctx.moveTo(82,690);ctx.lineTo(w-82,690);ctx.stroke();ctx.fillStyle='rgba(232,248,237,.46)';ctx.font='18px monospace';ctx.fillText('A QUIET MOMENT, KEPT FOR YOURSELF',82,754);ctx.fillStyle='#e8f7ec';ctx.font='34px "PingFang SC", "Microsoft YaHei", sans-serif';drawWrappedText(ctx,quote,82,840,840,54,2);ctx.fillStyle='rgba(232,248,237,.55)';ctx.font='18px "PingFang SC", "Microsoft YaHei", sans-serif';ctx.fillText('练习记录仅用于生成这张卡片，不包含身体分析数据。',82,1030);ctx.textAlign='right';ctx.fillStyle='#f2fbf4';ctx.font='500 25px monospace';ctx.fillText('HER MOTION',w-82,1230);ctx.textAlign='left';canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Card export failed')),'image/png')})}

